async function extractPdf(file){setProgress(5,'Loading PDF…');const pdfjs=await import('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.4.168/pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.4.168/pdf.worker.min.mjs';const data=new Uint8Array(await file.arrayBuffer());const pdf=await pdfjs.getDocument({data}).promise;let pages=[],chars=0;for(let i=1;i<=pdf.numPages;i++){setProgress(10+Math.round(35*i/pdf.numPages),`Extracting page ${i} of ${pdf.numPages}…`);const p=await pdf.getPage(i);const tc=await p.getTextContent();const text=tc.items.map(x=>x.str).join('\n');pages.push(text);chars+=text.replace(/\s/g,'').length;}
  let text=pages.join('\n');if(chars<80){if(!window.Tesseract)throw new Error('This PDF appears scanned and OCR could not be loaded.');pages=[];for(let i=1;i<=pdf.numPages;i++){setProgress(45+Math.round(30*i/pdf.numPages),`Running OCR… page ${i} of ${pdf.numPages}`);const p=await pdf.getPage(i);const vp=p.getViewport({scale:1.6});const c=document.createElement('canvas');c.width=vp.width;c.height=vp.height;await p.render({canvasContext:c.getContext('2d'),viewport:vp}).promise;const r=await Tesseract.recognize(c,'eng');pages.push(r.data.text);}text=pages.join('\n');}setProgress(82,'Detecting invoice fields…');await new Promise(r=>setTimeout(r,120));setProgress(94,'Preparing review…');return text;}
function friendlyError(err,context='operation'){
  const raw=String(err?.message||err||'').toLowerCase();
  if(raw.includes('duplicate')&&raw.includes('serial'))return 'A serial number already exists. Correct the serial number before saving.';
  if(raw.includes('row-level security')||raw.includes('permission')||raw.includes('admin access required')||raw.includes('editor or admin access required'))return 'Your account role does not allow this action. Please contact an Admin.';
  if(raw.includes('network')||raw.includes('fetch'))return 'Connection problem. Check your internet connection and try again.';
  if(context==='import')return 'Invoice could not be saved. No inventory changes were committed.';
  return 'Something went wrong. No changes were made. Please try again.';
}
function setHealth(status='live',text='Live'){const el=$('healthStatus');if(!el)return;el.classList.remove('live','reconnecting','offline');el.classList.add(status);el.innerHTML=`<i></i> ${text}`;}
function setProgress(p,t){$('importProgress').classList.remove('hidden');$('progressBar').style.width=p+'%';$('progressText').textContent=t;}
function parseDate(v=''){const s=v.trim();const m=s.match(/(\d{1,2})[\/-](\d{1,2})[\/-](\d{2,4})/);if(m){let y=+m[3];if(y<100)y+=2000;const day=+m[1],month=+m[2];if(day>=1&&day<=31&&month>=1&&month<=12)return `${y}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`;}let d=new Date(s);if(!isNaN(d))return d.toISOString().slice(0,10);return'';}
function detectInvoiceDate(text,invoice=''){
  const flat=String(text||'').replace(/\r/g,'');
  // 1) Strong labels: Invoice Date / Document Date / Tax Invoice Date.
  const strong=[
    /(?:invoice|document|tax\s*invoice)\s*date\s*[:#.-]?\s*(?:\n\s*)?([0-3]?\d[\/.-][01]?\d[\/.-](?:\d{2}|\d{4}))/i,
    /(?:invoice|document|tax\s*invoice)\s*date\s*[:#.-]?\s*(?:\n\s*)?([0-3]?\d\s+[A-Za-z]{3,9}\s+\d{2,4})/i
  ];
  for(const re of strong){const m=flat.match(re);if(m){const d=parseDate(m[1]);if(d)return d;}}
  // 2) OCR often puts column headings on one line and values on the next. For a recognised
  // invoice, inspect the neighbourhood around DATE and the invoice number for a plausible date.
  const isInvoice=/\b(?:tax\s+)?invoice\b/i.test(flat)||!!invoice;
  if(isInvoice){
    const lines=flat.split('\n').map(x=>x.trim()).filter(Boolean);
    const dateToken=/\b([0-3]?\d[\/.-][01]?\d[\/.-](?:\d{2}|\d{4}))\b/;
    for(let i=0;i<lines.length;i++){
      if(/^(?:invoice\s*)?date\b/i.test(lines[i])||/\bdate\b/i.test(lines[i])){
        for(let j=i;j<=Math.min(lines.length-1,i+4);j++){
          const m=lines[j].match(dateToken);if(m){const d=parseDate(m[1]);if(d)return d;}
        }
      }
    }
    if(invoice){
      const idx=flat.toLowerCase().indexOf(String(invoice).toLowerCase());
      if(idx>=0){const near=flat.slice(Math.max(0,idx-250),idx+500);const m=near.match(dateToken);if(m){const d=parseDate(m[1]);if(d)return d;}}
    }
  }
  // Supplier/OCR fallback: score all plausible dates and prefer one close to an invoice/date label.
  if(isInvoice){
    const rx=/\b([0-3]?\d[\/.\-][01]?\d[\/.\-](?:\d{2}|\d{4}))\b/g;let best=null,m;
    while((m=rx.exec(flat))){const d=parseDate(m[1]);if(!d)continue;const before=flat.slice(Math.max(0,m.index-140),m.index).toLowerCase();let score=0;if(/invoice\s*date|document\s*date|tax\s*invoice[^\n]{0,50}date/.test(before))score+=10;else if(/\bdate\b/.test(before))score+=6;if(invoice&&Math.abs(m.index-flat.toLowerCase().indexOf(String(invoice).toLowerCase()))<500)score+=4;if(!best||score>best.score)best={d,score};}
    if(best&&best.score>=4)return best.d;
  }
  return '';
}
function first(re,text,group=1){const m=text.match(re);return m?m[group].trim():'';}
function parseInvoice(text){const flat=text.replace(/\r/g,'');let supplier='';if(/Loud Technologies Asia/i.test(flat))supplier='Loud Technologies Asia Pte Ltd';else if(/AV\s+MEDIA\s+PTE\s+LTD/i.test(flat))supplier='AV Media Pte Ltd';else supplier=first(/([A-Z][A-Za-z0-9 &.,'-]+Pte\.?\s*Ltd\.?)/i,flat);
  let invoice='';
  // Supplier-aware patterns first so multi-part values such as "INV LTA-00215840" are not truncated to "INV".
  if(/Loud Technologies Asia/i.test(flat)) invoice=first(/\b(INV\s+LTA[- ]?\d+)\b/i,flat);
  if(!invoice&&/AV\s+MEDIA/i.test(flat)) invoice=first(/\b(VIN\d{2}[- ]?\d+)\b/i,flat);
  const invoicePatterns=[
    /(?:Invoice\s*(?:No\.?|Number|#)|Inv\s*(?:No\.?|#))\s*[:#-]?\s*(?:\n\s*)?((?:INV\s+)?[A-Z0-9][A-Z0-9._\/-]{2,}(?:\s+[A-Z0-9][A-Z0-9._\/-]{2,})?)/i,
    /(?:Tax\s+Invoice|Invoice)\s*[:#-]\s*((?:INV\s+)?[A-Z0-9][A-Z0-9._\/-]{2,}(?:\s+[A-Z0-9][A-Z0-9._\/-]{2,})?)/i,
    /\b(INV\s+[A-Z0-9][A-Z0-9._\/-]{3,})\b/i,
    /\b([A-Z]{2,6}\d{1,4}[-/][A-Z0-9-]{3,})\b/i
  ];
  if(!invoice){for(const re of invoicePatterns){const candidate=first(re,flat);if(candidate&&!/^(INV|INVOICE)$/i.test(candidate)){invoice=candidate;break;}}}
  invoice=String(invoice||'').replace(/\s+/g,' ').trim();
  // Never accept common invoice headings/labels as an invoice number.
  if(/^(sold\s*to|bill\s*to|ship\s*to|invoice|inv|invoice\s*(no|number)|date)$/i.test(invoice)) invoice='';
  let date=detectInvoiceDate(flat,invoice);
  const subtotal=num(first(/Subtotal\s*\n?\s*([\d,.]+)/i,flat)||first(/SUB\s*TOTAL\s*(?:SGD)?\s*([\d,.]+)/i,flat));const gst=num(first(/(?:GST\s*9%|Total Local supply of goods and services 9%)\s*(?:SGD)?\s*\n?\s*([\d,.]+)/i,flat));const total=num(first(/(?:Invoice Total SGD|AMOUNT\s*SGD)\s*\n?\s*([\d,.]+)/i,flat));
  const doc={supplier_name:canonicalSupplier(supplier),invoice_number:invoice,invoice_date:date,delivery_order_number:'',purchase_order_number:'',reference_number:first(/(?:Reference|REF\.\s*NO\.)\s*\n?\s*([^\n]+)/i,flat),currency:'SGD',subtotal,gst,total_amount:total};
  let items=[];if(/Loud Technologies Asia/i.test(flat))items=parseLoud(flat);else if(/AV\s+MEDIA/i.test(flat))items=parseAvMedia(flat);if(!items.length)items=[{sku:'',item_name:'',description:'',category:'',unit:'pcs',quantity:1,unit_price:null,amount:null,warranty:'',serials:''}];return{doc,items,rule:supplierRuleForText(flat)};}
function parseLoud(text){const products=[
  ['XVIVE-U35C','XVive U35C Wireless System','XVive U35C Wireless System for Condenser Microphones 5.8GHz','Audio / Wireless',4,340,1360,'1 Year','IntlE251100449, Intle251100452, Intle251000719, Intle251100448'],
  ['SHURE-SLXD2+-G66','Shure SLXD2+ SM58 Handheld Transmitter','Shure SLXD2+ Digital Wireless Handheld Microphone Transmitter with SM58 Cardioid Capsule (Freq: G66)','Audio / Wireless',1,480,480,'2 Years','3EL26704289, 3FA0985618'],
  ['GRAVITY-CART-M01B','Gravity CART M 01 B Multifunctional Trolley','Gravity CART M 01 B Multifunctional Trolley (Medium)','AV Accessories',2,170,340,'',''],
  ['XVIVE-AT2','XVive AT-2 Portable Audio Tester','XVive AT-2 Portable Audio Tester','Audio / Test Equipment',1,270,270,'1 Year','IntL260500638'],
  ['XVIVE-U3','Xvive Audio U3 Digital Wireless Microphone System','Xvive Audio U3 2.4 GHz Digital Wireless Microphone System for Dynamic Microphones','Audio / Wireless',4,275,1100,'1 Year','Int1241204279, Int1241204276, Int1241204210, Int1241203023']
 ];return products.filter(p=>text.toLowerCase().includes(p[2].slice(0,20).toLowerCase())).map(p=>({sku:p[0],item_name:p[1],description:p[2],category:p[3],unit:'pcs',quantity:p[4],unit_price:p[5],amount:p[6],warranty:p[7],serials:p[8]}));}
function parseAvMedia(text){let code=first(/(?:PRODUCT\s*NO\.?\s*)?\n?\s*(REMACO\s+MAS[- ]?2121)/i,text)||first(/\b(REMACO\s+MAS[- ]?\d+)\b/i,text);if(!code&&/MAS.?2121/i.test(text))code='REMACO MAS-2121';const qty=num(first(/(?:MAS[- ]?2121[^\n]*\n(?:[^\n]*\n){0,3}?)(\d+(?:\.\d+)?)\s*\n/i,text))||1;const unit=num(first(/\b290\.00\b/,text,0))||290;return /REMACO|MAS.?2121/i.test(text)?[{sku:(code||'REMACO MAS-2121').replace(/\s+/g,' ').replace('MAS 2121','MAS-2121'),item_name:'Manual Projection Screen',description:'Supply and install Remaco MAS2121 84\" x 84\" manual projection screen',category:'AV / Display',unit:'pcs',quantity:qty,unit_price:unit,amount:290,warranty:'',serials:''}]:[];}

function confidenceBadge(value,kind){let score=String(value??'').trim()?85:35;if(kind==='sku'&&String(value||'').length<3)score=45;if(kind==='qty'&&(!Number(value)||Number(value)<=0))score=30;const level=score>=80?'high':score>=55?'medium':'low';return `<span class="confidence ${level}" title="Parsing confidence">${score}%</span>`;}
function renderParsedItems(){const wrap=$('parsedItems');wrap.innerHTML=state.parsed.items.map((x,i)=>{const match=findBestItemMatch(x),matchHtml=match&&match.score<0.999?`<div class="sku-match-suggestion"><i data-lucide="wand-sparkles"></i><div><strong>Possible existing SKU · ${Math.round(match.score*100)}% match</strong><span>${esc(match.item.sku)} · ${esc(match.item.item_name)}</span></div><button type="button" class="secondary small-btn" data-use-match="${i}" data-match-id="${match.item.id}">Use existing</button></div>`:'';return `<div class="parsed-row ${!x.sku||!x.item_name?'needs-review':''}" data-pi="${i}"><div class="parsed-grid"><label>SKU / model ${confidenceBadge(x.sku,'sku')}<input data-f="sku" value="${esc(x.sku)}"></label><label>Standard item name<input data-f="item_name" value="${esc(x.item_name)}"></label><label>Qty ${confidenceBadge(x.quantity,'qty')}<input type="number" min="0.01" step="0.01" data-f="quantity" value="${x.quantity??1}"></label><label>Unit price<input type="number" step="0.01" data-f="unit_price" value="${x.unit_price??''}"></label><label>Amount<input type="number" step="0.01" data-f="amount" value="${x.amount??''}"></label><label>Description<textarea data-f="description" rows="2">${esc(x.description)}</textarea></label></div><div class="parsed-meta"><label>Category<input data-f="category" value="${esc(x.category||'')}"></label><label>Warranty<input data-f="warranty" value="${esc(x.warranty||'')}"></label><label>Serial numbers<input data-f="serials" value="${esc(x.serials||'')}"></label></div>${matchHtml}<div class="actions" style="margin-top:8px"><button type="button" data-remove-line="${i}">Remove line</button></div></div>`}).join('');window.lucide?.createIcons();}

function collectParsed(){document.querySelectorAll('.parsed-row').forEach(row=>{const i=+row.dataset.pi;row.querySelectorAll('[data-f]').forEach(el=>state.parsed.items[i][el.dataset.f]=el.type==='number'?num(el.value):el.value)});state.parsed.doc={supplier_name:canonicalSupplier($('pSupplier').value),invoice_number:$('pInvoice').value.trim(),invoice_date:String($('pDate').value||'').trim(),delivery_order_number:$('pDo').value.trim(),purchase_order_number:'',reference_number:$('pRef').value.trim(),currency:$('pCurrency').value.trim()||'SGD',subtotal:num($('pSubtotal').value),gst:num($('pGst').value),total_amount:num($('pTotal').value)};}
async function ensureUniqueFilename(file){
  let name=file.name.trim();
  while(await state.db.duplicateFilename(name)){
    const dot=name.lastIndexOf('.');
    const stem=dot>0?name.slice(0,dot):name;
    const ext=dot>0?name.slice(dot):'.pdf';
    const suggestion=`${stem} - copy${ext}`;
    const edited=window.prompt(`A document named "${name}" already exists. Please enter a different filename before importing.`,suggestion);
    if(edited===null){toast('Import cancelled. Filename was not changed.');return null;}
    name=edited.trim();
    if(!name){toast('Filename cannot be blank.');continue;}
    if(!/\.pdf$/i.test(name))name+='.pdf';
  }
  if(name===file.name)return file;
  return new File([file],name,{type:file.type||'application/pdf',lastModified:file.lastModified});
}

